sp_widget.script:
(function() {
  data.missingItems = [];
  data.applicationId = $sp.getParameter("app_id") || "";
  try {
    if (!data.applicationId) return;
    var appGr = new GlideRecord("x_1433041_identi_0_application");
    if (!appGr.get(data.applicationId)) return;

    // Check for unanswered mandatory questions
    var respGr = new GlideRecord("x_1433041_identi_0_response");
    respGr.addQuery("application", data.applicationId);
    respGr.addQuery("mandatory", true);
    respGr.addNullQuery("value");
    respGr.setLimit(50);
    respGr.query();
    while (respGr.next()) {
      data.missingItems.push({
        sys_id: respGr.getValue("sys_id"),
        question: respGr.getDisplayValue("question"),
        section: respGr.getDisplayValue("section"),
        type: "question"
      });
    }
  } catch (e) {
    gs.error("IBAR Missing Items widget error: " + e.message);
  }
})();
